select * from customer limit 3;

--Q1. What is the total revenue generated by male vs. female customers?
select gender, sum(purchase_amount) as total_revenue from customer  group by gender;

--Q2. Which customers used a discount but still spent more than the average purchase amount?
select customer_id,purchase_amount  from customer where discount_applied='Yes' and purchase_amount >(select avg(purchase_amount) from customer);

-- Q3. Which are the top 5 products with the highest average review rating?
select 	item_purchased, round(avg(review_rating)::numeric, 2) as avg_review_rating from customer group by item_purchased order by avg_review_rating desc limit 5;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
select round(avg(purchase_amount)::numeric, 3) as avg_purchase_amount, shipping_type from customer where shipping_type in ('Express', 'Standard') group by shipping_type;

--Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.
select subscription_status, round(avg(purchase_amount)::numeric, 3) as avg_spend, sum(purchase_amount) as total_revenue, 
count(*) as total_customers from customer group by subscription_status
order by avg_spend desc ; 

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased,
count(*) as total_purchases, 
count(*) filter (where discount_applied = 'Yes') as total_purchase_with_discount,
(count(*) filter (where discount_applied = 'Yes')/count(*)) *100.0 as perc_of_purchases
from customer group by item_purchased order by perc_of_purchases desc limit 5;	 


--Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment

select
case 
when previous_purchases<=1 then 'New'
when previous_purchases>=2 and previous_purchases<10 then 'Returning'
else 'Loyal'
end  as customer_segment,
count(*) as customer_count from customer group by customer_segment;

SELECT table_name 
FROM information_schema.tables 
WHERE table_schema = 'public';


--Q8. What are the top 3 most purchased products within each category? 

WITH item_counts AS (
    SELECT category,
           item_purchased,
           COUNT(customer_id) AS total_orders,
           ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT item_rank,category, item_purchased, total_orders
FROM item_counts
WHERE item_rank <=3;







